+import type { EventOf, SessionEvent } from '../types.ts';
+
+// One file as the run changed it. A snapshot patch gives added and removed lines; edit/write calls give
+// the text each call added and replaced. `deleted` is set when the file is gone.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+
+// Shortcuts that make work look done without being done. Each finding is one file, and one line for a line-level rule.
+export type SlopRule = 'test-deleted' | 'test-weakened' | 'test-skipped' | 'suppression' | 'swallowed-error' | 'type-escape' | 'stub';
+export type SlopFinding = { rule: SlopRule; path: string; line?: string };
+
+// How a finding reads in a reminder, the evidence flags and the receipt.
+export const findingText = (f: SlopFinding) => (f.line === undefined ? `${f.rule} ${f.path}` : `${f.rule} ${f.path}: ${f.line}`);
+
+const TEST_PATH = [
+  /(^|\/)(tests?|__tests__|spec|specs)\//,
+  /\.(test|spec|tests)\.[^/]+$/,
+  /(^|\/)(test_[^/]+|[^/]+_test\.[^/]+)$/,
+  /Tests?\.(java|kt|cs)$/,
+];
+
+export const isTestPath = (path: string) => TEST_PATH.some((re) => re.test(path));
+
+// Only code carries code slop: a markdown note that mentions `catch {}` is not an empty catch.
+const CODE = /\.(ts|tsx|mts|cts|js|jsx|mjs|cjs|py|go|rs|rb|java|kt|kts|cs|c|h|cc|cpp|hpp|swift|php|sh|bash|zsh)$/;
+
+const SKIP = [
+  /\b(?:test|it|describe|context|suite)\.(?:skip|todo)\s*\(/,
+  /\b(?:xit|xdescribe|xtest)\s*\(/,
+  /@pytest\.mark\.skip/,
+  /@unittest\.skip/,
+  /\bt\.Skip(?:f|Now)?\s*\(/,
+  /#\[ignore\]/,
+];
+
+const SUPPRESS = [
+  /@ts-(?:ignore|nocheck|expect-error)\b/,
+  /eslint-disable(?:-next-line|-line)?\b/,
+  /prettier-ignore\b/,
+  /#\s*type:\s*ignore/,
+  /#\s*noqa\b/,
+  /#\s*pylint:\s*disable/,
+  /\/\/\s*nolint\b/,
+  /#\[allow\(/,
+  /(?:biome-ignore|istanbul ignore|c8 ignore)\b/,
+];
+
+const SWALLOW = [
+  /catch\s*(?:\([^)]*\))?\s*\{\s*(?:(?:\/\/|\/\*)[^\n]*)?\s*\}/,
+  /\.catch\s*\(\s*(?:\(\s*\)|[A-Za-z_$][\w$]*)\s*=>\s*\{\s*\}\s*\)/,
+  /except[^:\n]*:\s*(?:pass|\.\.\.)\s*$/,
+];
+
+const ESCAPE = [/\bas\s+any\b/, /\bas\s+unknown\s+as\b/, /<any>/, /:\s*any\b/];
+
+const STUB = [/\bnot[ _-]?implemented/i, /unimplemented!/, /\bTODO\s*[:(]\s*(?:implement|finish)/i];
+
+// A test is weakened when it loses assertions without gaining as many: a rewritten assertion is fine.
+const ASSERTION = /\b(?:assert|expect|should|require)(?:!|\s|\(|\.)|\bassert_(?:eq|ne|matches)!|\.to(?:Be|Equal|StrictEqual|Throw|Match|Contain|HaveBeenCalled)\b/;
+const weakened = (c: FileChange) => c.removed.filter((l) => ASSERTION.test(l)).length > c.added.filter((l) => ASSERTION.test(l)).length;
+
+export function findSlop(changes: FileChange[]): SlopFinding[] {
+  const out: SlopFinding[] = [];
+  for (const c of changes) {
+    const path = c.path.replace(/\\/g, '/');
+    const test = isTestPath(path);
+    if (c.deleted) {
+      if (test) out.push({ rule: 'test-deleted', path });
+      continue;
+    }
+    if (test && weakened(c)) out.push({ rule: 'test-weakened', path });
+    if (!test && !CODE.test(path)) continue;
+    for (const line of c.added) {
+      const hit = test && SKIP.some((re) => re.test(line))
+        ? 'test-skipped'
+        : SUPPRESS.some((re) => re.test(line))
+          ? 'suppression'
+          : SWALLOW.some((re) => re.test(line))
+            ? 'swallowed-error'
+            : ESCAPE.some((re) => re.test(line))
+              ? 'type-escape'
+              : STUB.some((re) => re.test(line))
+                ? 'stub'
+                : undefined;
+      if (hit !== undefined) out.push({ rule: hit, path, line: line.trim() });
+    }
+  }
+  return out;
+}
+
+// Reads `git diff -U0` output (a patch, or `git diff-tree -p -U0`) into file changes.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  for (const line of patch.split('\n')) {
+    if (line.startsWith('diff --git ')) {
+      const m = /^diff --git a\/(.*) b\/(.*?)\/?$/.exec(line);
+      cur = m ? { path: m[2]!, added: [], removed: [], deleted: false } : undefined;
+      if (cur) out.push(cur);
+      continue;
+    }
+    if (!cur) continue;
+    if (line.startsWith('deleted file mode')) cur.deleted = true;
+    else if (line.startsWith('+++ ')) {
+      const name = line.slice(4).split('\t')[0]!;
+      if (name === '/dev/null') cur.deleted = true;
+      else cur.path = name.replace(/^b\//, '');
+    } else if (line.startsWith('--- ') || line.startsWith('index ') || line.startsWith('@@') || line.startsWith('\\') || line.startsWith('new file mode') || line.startsWith('old mode') || line.startsWith('new mode') || line.startsWith('similarity index') || line.startsWith('rename ')) {
+      continue;
+    } else if (line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
+
+// Without snapshots the changes come from the edit and write calls that completed.
+export function changesFromCalls(events: SessionEvent[]): FileChange[] {
+  const intents = new Map<string, EventOf<'tool_intent'>>();
+  const completed = new Set<string>();
+  for (const e of events) {
+    if (e.kind === 'tool_intent') intents.set(e.callId, e);
+    else if (e.kind === 'tool_result' && e.status === 'completed') completed.add(e.callId);
+  }
+  const byPath = new Map<string, FileChange>();
+  const change = (path: string) => {
+    const at = path.replace(/^\.\//, '');
+    if (!byPath.has(at)) byPath.set(at, { path: at, added: [], removed: [], deleted: false });
+    return byPath.get(at)!;
+  };
+  const lines = (text: unknown) => String(text ?? '').split('\n');
+  for (const [callId, e] of intents) {
+    if (!completed.has(callId)) continue;
+    const path = typeof e.input.path === 'string' ? e.input.path : undefined;
+    if (!path) continue;
+    const c = change(path);
+    if (e.tool === 'write') c.added.push(...lines(e.input.content));
+    else if (e.tool === 'edit' && Array.isArray(e.input.edits)) {
+      for (const edit of e.input.edits as { old_text?: unknown; new_text?: unknown }[]) {
+        c.removed.push(...lines(edit.old_text));
+        c.added.push(...lines(edit.new_text));
+      }
+    }
+  }
+  return [...byPath.values()];
+}
