+const SKIPS = [/\.(skip|todo|only)\s*\(/, /\bt\.Skip(f|Now)?\s*\(/, /\b(xit|xdescribe|xtest)\s*\(/, /pytest\.mark\.(skip|skipif|xfail)/, /@unittest\.skip/];
