+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules in README.md.
+describe('pricing rules', () => {
+  test('bulk tiers start at 10 and 50 units', () => {
+    // 10 pens = 1200, 5% off = 60; shipping 800; tax 7% of 1940 = 135.8 -> 136
+    expect(totals(cart('US', [['PEN', 10]]))).toMatchObject({ subtotal: 1140, coupon: 0, shipping: 800, tax: 136, total: 2076 });
+    // 50 pens = 6000, 10% off (not 5%) = 600; free shipping; tax 7% of 5400 = 378
+    expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+  });
+
+  test('lines of the same sku are merged before pricing', () => {
+    // 5 + 5 pens merge to 10 units and reach the 5% tier
+    const t = totals(cart('US', [['PEN', 5], ['PEN', 5]]));
+    expect(t.lines).toHaveLength(1);
+    expect(t.lines[0]).toMatchObject({ sku: 'PEN', quantity: 10, discount: 60 });
+    expect(t).toMatchObject({ subtotal: 1140, shipping: 800, tax: 136, total: 2076 });
+  });
+
+  test('shipping is free on the discounted subtotal', () => {
+    // 2 bags + 2 mugs = 5300; SAVE10 -530 -> 4770 < 5000, so shipping 800
+    // tax 7% of 5570 = 389.9 -> 390
+    expect(totals(cart('US', [['BAG', 2], ['MUG', 2]], 'SAVE10'))).toMatchObject({
+      subtotal: 5300,
+      coupon: 530,
+      shipping: 800,
+      tax: 390,
+      total: 5960,
+    });
+  });
+
+  test('UK free shipping starts at 4000', () => {
+    // 2 bags = 4400 >= 4000; tax 20% of 4400 = 880
+    expect(totals(cart('UK', [['BAG', 2]]))).toMatchObject({ subtotal: 4400, shipping: 0, tax: 880, total: 5280 });
+  });
+});

