@@ -0,0 +1,37 @@
+import { expect, test } from 'bun:test';
+import { formatDuration, parseDuration } from '../src/duration.ts';
+
+test('parseDuration accepts every unit and fractions', () => {
+  expect(parseDuration('1.5h')).toBe(5_400_000);
+  expect(parseDuration('2d 4h')).toBe(2 * 86_400_000 + 4 * 3_600_000);
+  expect(parseDuration('250ms')).toBe(250);
+  expect(parseDuration('1d')).toBe(86_400_000);
+  expect(parseDuration('2m')).toBe(120_000);
+  expect(parseDuration('0.5s')).toBe(500);
+  expect(parseDuration('1h 30m 15s 5ms')).toBe(5_400_000 + 15_000 + 5);
+});
+
+test('parseDuration ignores surrounding spaces', () => {
+  expect(parseDuration('  90s  ')).toBe(90_000);
+  expect(parseDuration('\t1h\n')).toBe(3_600_000);
+});
+
+test('parseDuration rejects anything else with the input in the message', () => {
+  for (const bad of ['', '10', '5x', 'h', '-1s', '1h 30', '1 h', '1..5s', '1s,2m']) {
+    expect(() => parseDuration(bad)).toThrow(`"${bad}"`);
+  }
+});
+
+test('formatDuration uses the largest units and leaves out zero parts', () => {
+  expect(formatDuration(0)).toBe('0s');
+  expect(formatDuration(1_500)).toBe('1s500ms');
+  expect(formatDuration(90_000)).toBe('1m30s');
+  expect(formatDuration(86_400_000)).toBe('1d');
+  expect(formatDuration(90_061_001)).toBe('1d1h1m1s1ms');
+  expect(formatDuration(999)).toBe('999ms');
+  expect(formatDuration(2 * 86_400_000 + 3 * 3_600_000)).toBe('2d3h');
+});
+
+test('formatDuration throws on a negative number', () => {
+  expect(() => formatDuration(-1)).toThrow();
+});
