@@ -0,0 +1,124 @@
+import { expect, test } from 'bun:test';
+import { LRU } from '../src/lru.ts';
+
+test('lru evicts the least recently used entry over capacity', () => {
+  const seen: [string, number, string][] = [];
+  const cache = new LRU<string, number>(2, 10_000, () => 0);
+  cache.onEvict = (key, value, reason) => seen.push([key, value, reason]);
+
+  cache.set('a', 1);
+  cache.set('b', 2);
+  cache.get('a');
+  cache.set('c', 3);
+
+  expect(seen).toEqual([['b', 2, 'capacity']]);
+  expect(cache.keys()).toEqual(['c', 'a']);
+  expect(cache.get('b')).toBeUndefined();
+});
+
+test('lru expires entries and reports it', () => {
+  let t = 0;
+  const seen: [string, number, string][] = [];
+  const cache = new LRU<string, number>(5, 100, () => t);
+  cache.onEvict = (key, value, reason) => seen.push([key, value, reason]);
+
+  cache.set('a', 1);
+  t = 99;
+  expect(cache.get('a')).toBe(1);
+  t = 100;
+  expect(cache.get('a')).toBeUndefined();
+  expect(seen).toEqual([['a', 1, 'expired']]);
+  expect(cache.size).toBe(0);
+});
+
+test('lru counts only live entries and orders keys by recency', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(5, 100, () => t);
+  cache.set('a', 1);
+  t = 50;
+  cache.set('b', 2);
+  cache.get('a');
+
+  expect(cache.size).toBe(2);
+  expect(cache.keys()).toEqual(['a', 'b']);
+
+  t = 120;
+  expect(cache.size).toBe(1);
+  expect(cache.keys()).toEqual(['b']);
+});
+
+test('lru set refreshes the ttl', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.set('a', 1);
+  t = 80;
+  cache.set('a', 2);
+  t = 150;
+  expect(cache.get('a')).toBe(2);
+  t = 180;
+  expect(cache.get('a')).toBeUndefined();
+});
+
+test('lru delete distinguishes live and expired entries', () => {
+  let t = 0;
+  const seen: [string, number, string][] = [];
+  const cache = new LRU<string, number>(5, 100, () => t);
+  cache.onEvict = (key, value, reason) => seen.push([key, value, reason]);
+
+  cache.set('a', 1);
+  cache.set('b', 2);
+  t = 100;
+
+  expect(cache.delete('a')).toBe(false);
+  expect(cache.delete('b')).toBe(false);
+  expect(cache.delete('missing')).toBe(false);
+  expect(seen).toEqual([
+    ['a', 1, 'expired'],
+    ['b', 2, 'expired'],
+  ]);
+
+  t = 200;
+  cache.set('c', 3);
+  t = 250;
+  expect(cache.delete('c')).toBe(true);
+  expect(seen.at(-1)).toEqual(['c', 3, 'delete']);
+  expect(cache.size).toBe(0);
+});
+
+test('lru removes expired entries before evicting a live one', () => {
+  let t = 0;
+  const seen: [string, number, string][] = [];
+  const cache = new LRU<string, number>(3, 100, () => t);
+  cache.onEvict = (key, value, reason) => seen.push([key, value, reason]);
+
+  cache.set('a', 1);
+  cache.set('b', 2);
+  cache.set('c', 3);
+  t = 100;
+  cache.set('d', 4);
+
+  expect(seen).toEqual([
+    ['a', 1, 'expired'],
+    ['b', 2, 'expired'],
+    ['c', 3, 'expired'],
+  ]);
+  expect(cache.keys()).toEqual(['d']);
+});
+
+test('lru keeps a cache at capacity when nothing expired', () => {
+  const seen: [string, number, string][] = [];
+  const cache = new LRU<string, number>(2, 10_000, () => 0);
+  cache.onEvict = (key, value, reason) => seen.push([key, value, reason]);
+
+  cache.set('a', 1);
+  cache.set('b', 2);
+  cache.set('c', 3);
+  cache.set('d', 4);
+
+  expect(seen).toEqual([
+    ['a', 1, 'capacity'],
+    ['b', 2, 'capacity'],
+  ]);
+  expect(cache.keys()).toEqual(['d', 'c']);
+  expect(cache.size).toBe(2);
+});
