@@ -0,0 +1,36 @@
+import { expect, test } from 'bun:test';
+import { slugify, uniqueSlug } from '../src/slug.ts';
+
+test('slugify drops diacritics', () => {
+  expect(slugify('ÀÉÎÕÜ àéîõü')).toBe('aeiou-aeiou');
+  expect(slugify('Ça va? naïve señor źdźbło')).toBe('ca-va-naive-senor-zdzblo');
+  expect(slugify('Žluťoučký kůň')).toBe('zlutoucky-kun');
+});
+
+test('slugify expands letters without a plain decomposition', () => {
+  expect(slugify('Straße')).toBe('strasse');
+  expect(slugify('Æsir œuvre Øresund')).toBe('aesir-oeuvre-oresund');
+  expect(slugify('Łódź Đặng')).toBe('lodz-dang');
+});
+
+test('slugify collapses separators and trims them', () => {
+  expect(slugify('  --Hello,,,  World!!  ')).toBe('hello-world');
+  expect(slugify('a_b/c.d')).toBe('a-b-c-d');
+  expect(slugify('!!!')).toBe('');
+});
+
+test('slugify cuts to max without a dangling dash', () => {
+  expect(slugify('ab-cd-ef', 5)).toBe('ab-cd');
+  expect(slugify('ab-cd-ef', 6)).toBe('ab-cd');
+  expect(slugify('abcdef', 3)).toBe('abc');
+  expect(slugify('abc-def', 3)).toBe('abc');
+  expect(slugify('ab-cdef', 4)).toBe('ab');
+  expect(slugify('ab-cd', 100)).toBe('ab-cd');
+  expect(slugify('ab-cd', 4)).toBe('ab');
+});
+
+test('uniqueSlug picks the first free suffix', () => {
+  expect(uniqueSlug('post', new Set())).toBe('post');
+  expect(uniqueSlug('post', new Set(['post', 'post-2', 'post-3']))).toBe('post-4');
+  expect(uniqueSlug('post', new Set(['post-2']))).toBe('post');
+});

