 //   keeps exactly max ("ab-cd-ef" with max 5 is "ab-cd").
 //
 // uniqueSlug(slug, taken): slug itself if it is not in taken, else slug-2, slug-3, ... the first free one.
+const SPECIAL: Record<string, string> = {
+  ß: 'ss',
+  æ: 'ae',
+  œ: 'oe',
+  ø: 'o',
+  ł: 'l',
+  đ: 'd',
+};
+
+function truncate(slug: string, max: number): string {
+  if (max <= 0) return '';
+  const cut = slug.lastIndexOf('-', max);
+  return cut > 0 ? slug.slice(0, cut) : slug.slice(0, max);
+}
+
 export function slugify(text: string, max?: number): string {
-  throw new Error('not implemented');
+  const plain = text
+    .toLowerCase()
+    .normalize('NFD')
+    .replace(/\p{M}/gu, '')
+    .replace(/[ßæœøłđ]/g, (char) => SPECIAL[char]!);
+
+  const slug = plain.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
+
+  return max !== undefined && slug.length > max ? truncate(slug, max) : slug;
 }

 export function uniqueSlug(slug: string, taken: Set<string>): string {
-  throw new Error('not implemented');
+  if (!taken.has(slug)) return slug;
+  let n = 2;
+  while (taken.has(`${slug}-${n}`)) n++;
+  return `${slug}-${n}`;
 }
diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/extra-rules.test.ts b/test/extra-rules.test.ts
--- a/test/extra-rules.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/extra-rules.test.ts	2026-10-29 05:54:35.184297833 +0000
@@ -0,0 +1,143 @@
+import { expect, test } from 'bun:test';
+import { formatDuration, parseDuration } from '../src/duration.ts';
+import { slugify, uniqueSlug } from '../src/slug.ts';
+import { LRU } from '../src/lru.ts';
+
+test('parseDuration units, fractions and spaces', () => {
+  expect(parseDuration('250ms')).toBe(250);
+  expect(parseDuration('2d 4h')).toBe(2 * 86_400_000 + 4 * 3_600_000);
+  expect(parseDuration('1.5h')).toBe(5_400_000);
+  expect(parseDuration('  1h  30m  ')).toBe(5_400_000);
+  expect(parseDuration('1m')).toBe(60_000);
+  expect(parseDuration('1h30m15s250ms')).toBe(5_415_250);
+});
+
+test('parseDuration rounds to whole milliseconds', () => {
+  expect(parseDuration('1.5ms')).toBe(2);
+  expect(parseDuration('0.4ms')).toBe(0);
+});
+
+test('parseDuration rejects malformed input', () => {
+  for (const bad of ['', '   ', '10', '5x', 'h', '-1s', '1h 30', '1 h', '1.2.3s', '1h5']) {
+    expect(() => parseDuration(bad)).toThrow(`"${bad}"`);
+  }
+});
+
+test('formatDuration uses the largest units and drops zero parts', () => {
+  expect(formatDuration(0)).toBe('0s');
+  expect(formatDuration(1_500)).toBe('1s500ms');
+  expect(formatDuration(3_600_000)).toBe('1h');
+  expect(formatDuration(86_400_000 + 3_600_000 + 60_000 + 1_000 + 1)).toBe('1d1h1m1s1ms');
+  expect(formatDuration(2 * 86_400_000)).toBe('2d');
+});
+
+test('formatDuration throws on negative input', () => {
+  expect(() => formatDuration(-1)).toThrow();
+});
+
+test('formatDuration round-trips through parseDuration', () => {
+  expect(parseDuration(formatDuration(123_456_789))).toBe(123_456_789);
+});
+
+test('slugify strips diacritics and expands special letters', () => {
+  expect(slugify('ÀÇ Ñ ź')).toBe('ac-n-z');
+  expect(slugify('Straße')).toBe('strasse');
+  expect(slugify('aæ œ ø ł đ')).toBe('aae-oe-o-l-d');
+});
+
+test('slugify collapses separators and trims edges', () => {
+  expect(slugify('  Hello -- World!!  ')).toBe('hello-world');
+  expect(slugify('---')).toBe('');
+  expect(slugify('a_b.c/d')).toBe('a-b-c-d');
+  expect(slugify('Ünïcode 123')).toBe('unicode-123');
+});
+
+test('slugify max cuts at the last dash that fits', () => {
+  expect(slugify('ab-cd-ef', 5)).toBe('ab-cd');
+  expect(slugify('ab-cd-ef', 4)).toBe('ab');
+  expect(slugify('abcdef-gh', 5)).toBe('abcde');
+  expect(slugify('abcdef-gh', 7)).toBe('abcdef');
+  expect(slugify('hello', 0)).toBe('');
+  expect(slugify('hello-world', 20)).toBe('hello-world');
+});
+
+test('uniqueSlug skips every taken suffix', () => {
+  expect(uniqueSlug('post', new Set())).toBe('post');
+  expect(uniqueSlug('post', new Set(['post', 'post-2', 'post-3']))).toBe('post-4');
+});
+
+test('lru promotes hits and reports expiration on get', () => {
+  let t = 0;
+  const events: string[] = [];
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.onEvict = (key, value, reason) => events.push(`${key}:${value}:${reason}`);
+
+  cache.set('a', 1);
+  t = 50;
+  cache.set('b', 2);
+  expect(cache.get('a')).toBe(1);
+  expect(cache.keys()).toEqual(['a', 'b']);
+
+  t = 100; // 'a' expires at 100, 'b' at 150
+  expect(cache.get('a')).toBeUndefined();
+  expect(events).toEqual(['a:1:expired']);
+  expect(cache.size).toBe(1);
+  expect(cache.keys()).toEqual(['b']);
+});
+
+test('lru evicts the least recently used on overflow', () => {
+  const events: string[] = [];
+  const cache = new LRU<string, number>(2, 1000);
+  cache.onEvict = (key, _value, reason) => events.push(`${key}:${reason}`);
+
+  cache.set('a', 1);
+  cache.set('b', 2);
+  cache.get('a');
+  cache.set('c', 3);
+  expect(events).toEqual(['b:capacity']);
+  expect(cache.keys()).toEqual(['c', 'a']);
+  expect(cache.get('b')).toBeUndefined();
+  expect(events).toEqual(['b:capacity']);
+});
+
+test('lru set removes expired entries before live ones', () => {
+  let t = 0;
+  const events: string[] = [];
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.onEvict = (key, _value, reason) => events.push(`${key}:${reason}`);
+
+  cache.set('old', 1); // expires at 100
+  t = 100;
+  cache.set('live', 2); // over capacity is not yet reached, 'old' stays stored
+  cache.set('new', 3); // over capacity: 'old' is removed as expired
+  expect(events).toEqual(['old:expired']);
+  expect(cache.keys()).toEqual(['new', 'live']);
+  expect(cache.size).toBe(2);
+});
+
+test('lru delete distinguishes live, expired and missing keys', () => {
+  let t = 0;
+  const events: string[] = [];
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.onEvict = (key, _value, reason) => events.push(`${key}:${reason}`);
+
+  cache.set('a', 1);
+  t = 100;
+  cache.set('b', 2); // 'a' is stored but expired
+  expect(cache.delete('a')).toBe(false);
+  expect(cache.delete('b')).toBe(true);
+  expect(cache.delete('missing')).toBe(false);
+  expect(events).toEqual(['a:expired', 'b:delete']);
+});
+
+test('lru overwriting a key refreshes its ttl and position', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  t = 50;
+  cache.set('a', 10); // fresh ttl, now most recently used
+  expect(cache.keys()).toEqual(['a', 'b']);
+  t = 100; // the original 'a' would have expired, the new one lives until 150
+  expect(cache.get('a')).toBe(10);
+});
